from __future__ import annotations

import json

from .models import HuntReport, HuntRequest


def report_json(report: HuntReport) -> str:
    return report.model_dump_json(indent=2)


def regression_test_source(request: HuntRequest, report: HuntReport) -> str:
    lines = [
        "# Generated by AI Failure Hunter. Review before running.",
        request.source.rstrip(),
        "",
        "def test_discovered_regressions():",
    ]
    confirmed = [failure for failure in report.failures if failure.verification_status == "confirmed"]
    if not confirmed:
        lines.append("    pass  # No confirmed failures were available for regression assertions.")
        return "\n".join(lines) + "\n"
    for failure in confirmed:
        args = failure.minimized_input or failure.original_input
        call = f"{request.function_name}(**{repr(args)})"
        lines.append(f"    # {failure.failure_id}: {failure.expected}")
        if request.oracle == "sorted":
            first = next(iter(args.values()), None)
            lines.append(f"    assert {call} == sorted({repr(first)})")
        elif request.oracle == "sum":
            first = next(iter(args.values()), None)
            lines.append(f"    assert {call} == sum({repr(first)})")
        elif request.oracle == "identity":
            first = next(iter(args.values()), None)
            lines.append(f"    assert {call} == {repr(first)}")
        elif request.oracle == "non_negative":
            lines.append(f"    assert {call} >= 0")
        else:
            lines.append(f"    {call}  # Regression passes when this no longer raises.")
    return "\n".join(lines) + "\n"

